     1	/**
     2	 * Maps a Commerce API product onto the props the PDP's static-information components take.
     3	 *
     4	 * Extracted from the page so the mapping is unit-testable on its own. Nothing else on the PDP
     5	 * ties an external field name to a rendered prop, and a mis-keyed field here does not fail
     6	 * loudly: it falls through to `undefined`, the component returns `null`, and the page renders
     7	 * a plausible-looking product with one line quietly missing. Neither a Storybook `play`
     8	 * (which supplies its own props) nor an axe run can see that.
     9	 */
    10	
    11	/*
    12	 * The Commerce SDK's `Product` type does not carry Zimmermann's `c_*` custom attributes, and
    13	 * `@salesforce/retail-react-app` ships no types at all. This is the narrow shape this mapping
    14	 * actually reads — everything optional, because every one of these fields can be absent on a
    15	 * real catalogue product.
    16	 */
    17	export type PdpSourceProduct = {
    18	  id?: string;
    19	  name?: string;
    20	  longDescription?: string;
    21	  /** Master product reference. Present on a variant; absent on a standard product. */
    22	  master?: { masterId?: string };
    23	  /** Zimmermann custom attribute holding the model's measurements and worn size. */
    24	  c_modelFit?: string;
    25	};
    26	
    27	/** The subset of `getPriceData`'s result this mapping needs. */
    28	export type PdpSourcePrice = {
    29	  currentPrice?: number;
    30	  /** True when the variant's selling price is below its list (RRP) price — PRC-09. */
    31	  isOnSale?: boolean;
    32	  /** The original RRP. Present when `isOnSale` is true. */
    33	  listPrice?: number;
    34	};
    35	
    36	/** Formats a bare amount for the storefront. Injected so this module stays free of react-intl. */
    37	export type FormatPrice = (amount: number, currency: string) => string;
    38	
    39	export type PdpProductInfo = {
    40	  name: string;
    41	  /** Active selling price (the "Now" price when on sale). */
    42	  price: string;
    43	  /** Original RRP. Present only when the product is on sale (PRC-09). */
    44	  wasPrice?: string;
    45	  description?: string;
    46	  modelInfo?: string;
    47	  styleCode?: string;
    48	};
    49	
    50	/**
    51	 * @param product - The resolved product (variant when one is selected, master otherwise).
    52	 * @param priceData - `getPriceData(...)`'s result, as ProductView computes it.
    53	 * @param currency - The storefront's active currency code.
    54	 * @param formatPrice - Currency formatter, normally `intl.formatNumber`.
    55	 * @returns Props for the static-information components, or `null` while the product loads.
    56	 */
    57	export const selectPdpProductInfo = (
    58	  product: PdpSourceProduct | undefined | null,
    59	  priceData: PdpSourcePrice | undefined | null,
    60	  currency: string,
    61	  formatPrice: FormatPrice,
    62	): PdpProductInfo | null => {
    63	  if (!product?.name) return null;
    64	
    65	  return {
    66	    name: product.name,
    67	    price: typeof priceData?.currentPrice === 'number' ? formatPrice(priceData.currentPrice, currency) : '',
    68	    // PRC-09: expose the original RRP as wasPrice only when the item is genuinely on sale and
    69	    // the list price is a real number. The Was/Now atoms branch on its presence; when absent
    70	    // ZimmProductPrice renders the standard single-price treatment.
    71	    wasPrice:
    72	      priceData?.isOnSale && typeof priceData.listPrice === 'number'
    73	        ? formatPrice(priceData.listPrice, currency)
    74	        : undefined,
    75	    description: product.longDescription,
    76	    modelInfo: product.c_modelFit,
    77	    // The style code shoppers see is the *master* style number. `product.id` is the variant
    78	    // SKU once a size is selected, so reading it would silently show a different value after
    79	    // the first swatch click. Standard products have no master, and there `id` is correct.
    80	    styleCode: product.master?.masterId ?? product.id,
    81	  };
    82	};
=== productInfo.test.ts ===
     1	/**
     2	 * G1 — ties the external data shape to the rendered props.
     3	 *
     4	 * Every assertion below uses a value unique to its own field, so a mapping that reads the
     5	 * wrong key fails rather than coincidentally matching. That is the whole point: the failure
     6	 * mode this guards is a field quietly resolving to `undefined` and its line disappearing.
     7	 */
     8	import { describe, expect, test, vi } from 'vitest';
     9	import { selectPdpProductInfo, type PdpSourceProduct, type PdpSourcePrice } from './productInfo';
    10	
    11	/** Distinct sentinel per field — no two share a value. */
    12	const FULL: PdpSourceProduct = {
    13	  id: 'VARIANT-SKU-0001',
    14	  name: 'Natura Mini Dress',
    15	  longDescription: '<p>A long sleeve linen mini dress.</p>',
    16	  master: { masterId: 'MASTER-STYLE-8637' },
    17	  c_modelFit: 'Model is 178cm and wears a size 0',
    18	};
    19	
    20	const formatPrice = (amount: number, currency: string) => `${currency} ${amount.toFixed(2)}`;
    21	const map = (
    22	  product: PdpSourceProduct | null | undefined,
    23	  price: PdpSourcePrice | null = { currentPrice: 895 },
    24	) => selectPdpProductInfo(product, price, 'AUD', formatPrice);
    25	
    26	describe('selectPdpProductInfo — every field reaches the right prop', () => {
    27	  test.each`
    28	    prop             | source                      | expected
    29	    ${'name'}        | ${'name'}                   | ${'Natura Mini Dress'}
    30	    ${'description'} | ${'longDescription'}        | ${'<p>A long sleeve linen mini dress.</p>'}
    31	    ${'modelInfo'}   | ${'c_modelFit'}             | ${'Model is 178cm and wears a size 0'}
    32	    ${'styleCode'}   | ${'master.masterId'}        | ${'MASTER-STYLE-8637'}
    33	    ${'price'}       | ${'priceData.currentPrice'} | ${'AUD 895.00'}
    34	  `('$prop <- $source', ({ prop, expected }) => {
    35	    expect(map(FULL)?.[prop as keyof ReturnType<typeof map> & string]).toBe(expected);
    36	  });
    37	
    38	  test('styleCode is the master style number, not the variant id', () => {
    39	    // The regression this pins: after the first swatch click `product.id` becomes the variant
    40	    // SKU while the style code shown to shoppers must not change.
    41	    expect(map(FULL)?.styleCode).toBe('MASTER-STYLE-8637');
    42	    expect(map(FULL)?.styleCode).not.toBe(FULL.id);
    43	  });
    44	
    45	  test('falls back to product.id for a standard product with no master', () => {
    46	    expect(map({ ...FULL, master: undefined })?.styleCode).toBe('VARIANT-SKU-0001');
    47	  });
    48	});
    49	
    50	describe('selectPdpProductInfo — absent fields', () => {
    51	  test.each(['longDescription', 'c_modelFit', 'master'] as const)(
    52	    'a missing %s yields undefined, not a blank string',
    53	    (field) => {
    54	      const info = map({ ...FULL, [field]: undefined });
    55	      expect(info).not.toBeNull();
    56	      // `undefined` matters: the atoms branch on it to render nothing at all. An empty string
    57	      // would still be truthy at some call sites and could render an empty styled node.
    58	      const byField = { longDescription: 'description', c_modelFit: 'modelInfo', master: 'styleCode' } as const;
    59	      if (field !== 'master') expect(info?.[byField[field]]).toBeUndefined();
    60	    },
    61	  );
    62	
    63	  test('only name is load-bearing — no name means nothing to render yet', () => {
    64	    expect(map(undefined)).toBeNull();
    65	    expect(map(null)).toBeNull();
    66	    expect(map({ ...FULL, name: undefined })).toBeNull();
    67	    expect(map({ ...FULL, name: '' })).toBeNull();
    68	  });
    69	
    70	  test('an absent price renders empty rather than "NaN" or "undefined"', () => {
    71	    expect(map(FULL, null)?.price).toBe('');
    72	    expect(map(FULL, {})?.price).toBe('');
    73	    expect(map(FULL, { currentPrice: undefined })?.price).toBe('');
    74	  });
    75	
    76	  test('a genuine zero price is formatted, not treated as absent', () => {
    77	    expect(map(FULL, { currentPrice: 0 })?.price).toBe('AUD 0.00');
    78	  });
    79	});
    80	
    81	describe('selectPdpProductInfo — formatting is delegated', () => {
    82	  test('calls the injected formatter once with the storefront currency', () => {
    83	    const spy = vi.fn(() => '$895.00');
    84	    selectPdpProductInfo(FULL, { currentPrice: 895 }, 'AUD', spy);
    85	    expect(spy).toHaveBeenCalledOnce();
    86	    expect(spy).toHaveBeenCalledWith(895, 'AUD');
    87	  });
    88	
    89	  test('does no formatting of its own', () => {
    90	    // Guards against a future edit reintroducing a hardcoded symbol or locale here; currency
    91	    // presentation differs across the 8 storefronts and belongs to react-intl.
    92	    expect(selectPdpProductInfo(FULL, { currentPrice: 895 }, 'HKD', (a, c) => `${c}${a}`)?.price).toBe('HKD895');
    93	  });
    94	});
    95	
    96	// ---------------------------------------------------------------------------
    97	// PRC-09 — Was/Now sale price (SFCC-194)
    98	// ---------------------------------------------------------------------------
    99	
   100	describe('selectPdpProductInfo — wasPrice (PRC-09)', () => {
   101	  const mapSale = (priceData: Parameters<typeof map>[1]) => map(FULL, priceData);
   102	
   103	  // AC1: sale active — wasPrice is the formatted listPrice
   104	  test('returns wasPrice when isOnSale is true and listPrice is a number', () => {
   105	    const info = mapSale({ currentPrice: 450, isOnSale: true, listPrice: 595 });
   106	    expect(info?.wasPrice).toBe('AUD 595.00');
   107	    expect(info?.price).toBe('AUD 450.00');
   108	  });
   109	
   110	  // AC2: no sale — wasPrice is absent
   111	  test('returns undefined wasPrice when isOnSale is false', () => {
   112	    const info = mapSale({ currentPrice: 595, isOnSale: false, listPrice: 595 });
   113	    expect(info?.wasPrice).toBeUndefined();
   114	  });
   115	
   116	  // AC2: standard product (no priceData sale fields) — wasPrice is absent
   117	  test('returns undefined wasPrice when isOnSale is absent', () => {
   118	    const info = mapSale({ currentPrice: 595 });
   119	    expect(info?.wasPrice).toBeUndefined();
   120	  });
   121	
   122	  // AC4: sale expired — listPrice removed or equal to currentPrice, isOnSale becomes false
   123	  test('returns undefined wasPrice when isOnSale is true but listPrice is absent', () => {
   124	    // BM can mark isOnSale:true but provide no listPrice; the atom must not render "Was undefined"
   125	    const info = mapSale({ currentPrice: 450, isOnSale: true, listPrice: undefined });
   126	    expect(info?.wasPrice).toBeUndefined();
   127	  });
   128	
   129	  // Formatter is called for wasPrice with the same currency as price
   130	  test('formats wasPrice with the same injected formatter and currency as price', () => {
   131	    const spy = vi.fn((amount: number, currency: string) => `${currency}${amount}`);
   132	    selectPdpProductInfo(FULL, { currentPrice: 450, isOnSale: true, listPrice: 595 }, 'AUD', spy);
   133	    expect(spy).toHaveBeenCalledTimes(2);
   134	    expect(spy).toHaveBeenCalledWith(595, 'AUD');
   135	  });
   136	});

